// GET /api/resolve?url=<link Google Maps>
// 1. Mengikuti redirect link pendek (maps.app.goo.gl, goo.gl/maps, dll) secara server-side.
// 2. Mem-parse link rute (/maps/dir/... atau ?api=1&origin=&destination=) jadi daftar waypoint.
// 3. Mem-parse link tempat tunggal (@lat,lng, ?q=, data=!3d/!4d) jadi { name, lat, lng }.

const ALLOWED_HOSTS = new Set([
  "maps.app.goo.gl",
  "goo.gl",
  "www.google.com",
  "google.com",
  "maps.google.com",
  "www.google.co.id",
  "google.co.id",
]);

const UA = { "User-Agent": "Mozilla/5.0 (compatible; TemanJalan/1.0)" };

function parseLatLng(s) {
  if (!s) return null;
  const m = String(s)
    .trim()
    .match(/^(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)$/);
  if (!m) return null;
  const lat = parseFloat(m[1]);
  const lng = parseFloat(m[2]);
  if (Math.abs(lat) > 90 || Math.abs(lng) > 180) return null;
  return { lat, lng };
}

// "Monas, Jakarta" atau "-6.175,106.827" -> { name, lat?, lng? }
function toWaypoint(raw) {
  const s = String(raw || "").trim();
  if (!s) return null;
  const ll = parseLatLng(s);
  return ll ? { name: s, lat: ll.lat, lng: ll.lng } : { name: s };
}

function parsePlace(u) {
  // 1. @lat,lng,zoom
  let m = u.pathname.match(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/);
  if (m) {
    const q = u.searchParams.get("q") || u.searchParams.get("query");
    return { name: q ? decodeURIComponent(q) : null, lat: parseFloat(m[1]), lng: parseFloat(m[2]) };
  }
  // 2. ?q= / ?query=
  const q = u.searchParams.get("q") || u.searchParams.get("query");
  if (q) {
    const ll = parseLatLng(q);
    return ll
      ? { name: null, lat: ll.lat, lng: ll.lng }
      : { name: q, lat: null, lng: null };
  }
  // 3. data=!...!3dLAT!4dLNG
  m = u.href.match(/!3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/);
  if (m) return { name: null, lat: parseFloat(m[1]), lng: parseFloat(m[2]) };
  return null;
}

function parseDir(u) {
  // Gaya 1: ?api=1&origin=..&destination=..&waypoints=a|b
  const origin = u.searchParams.get("origin");
  const destination = u.searchParams.get("destination");
  if (origin || destination) {
    const wps = [];
    const push = (v) => {
      const w = toWaypoint(v);
      if (w) wps.push(w);
    };
    push(origin);
    const via = u.searchParams.get("waypoints");
    if (via) via.split("|").forEach(push);
    push(destination);
    return wps.length ? wps : null;
  }
  // Gaya 2: /maps/dir/Asal/Tujuan[/...]
  const m = u.pathname.match(/\/maps\/dir\/([^?#]*)/);
  if (m) {
    const wps = m[1]
      .split("/")
      .map((s) => {
        try {
          return decodeURIComponent(s);
        } catch {
          return s;
        }
      })
      .filter((s) => s && !s.startsWith("@"))
      .map(toWaypoint)
      .filter(Boolean);
    return wps.length ? wps : null;
  }
  return null;
}

export default async function handler(req, res) {
  const { url } = req.query;

  if (!url || typeof url !== "string" || !/^https?:\/\//i.test(url)) {
    return res.status(400).json({ error: "Parameter 'url' tidak valid." });
  }

  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return res.status(400).json({ error: "URL tidak bisa dibaca." });
  }

  if (!ALLOWED_HOSTS.has(parsed.hostname.toLowerCase())) {
    return res.status(400).json({ error: "Host URL tidak didukung. Pakai link Google Maps." });
  }

  try {
    let current = parsed.toString();
    for (let i = 0; i < 10; i++) {
      const r = await fetch(current, { redirect: "manual", headers: UA });
      const loc = r.headers.get("location");
      if (loc && [301, 302, 303, 307, 308].includes(r.status)) {
        current = new URL(loc, current).toString();
        continue;
      }
      break;
    }

    const u = new URL(current);
    const waypoints = parseDir(u);
    const place = waypoints ? null : parsePlace(u);

    return res.status(200).json({ resolved: current, waypoints, place });
  } catch (e) {
    return res.status(502).json({ error: "Gagal me-resolve link." });
  }
}

// GET /api/place?q=<nama>&lat=<lat>&lng=<lng>
// Menggabungkan: Foursquare (detail + rating + tips/ulasan), OpenStreetMap/Nominatim
// (alamat & jam buka), Wikipedia (ringkasan). Tips dipilah otomatis menjadi
// Kelebihan vs Kekurangan berdasarkan kata kunci (ID + EN).
//
// API key Foursquare dibaca dari env FOURSQUARE_API_KEY (JANGAN di-commit).
// Tanpa key: tetap mengembalikan info dasar dari OSM + Wikipedia dengan flag needsKey.

const UA = { "User-Agent": "Mozilla/5.0 (compatible; TemanJalan/1.0)" };
const FSQ = "https://api.foursquare.com/v3/places";

const POSITIVE = [
  // Indonesia
  "bagus", "enak", "nyaman", "bersih", "rapi", "ramah", "murah", "mantap", "keren",
  "luas", "sejuk", "adem", "tenang", "indah", "puas", "cepat", "lengkap", "lengkap",
  "terbaik", "luar biasa", "wajib", "suka", "recommended", "rekomended", "rekomendasi",
  "asyik", "seru", "oke banget", "top", "juara", "bersahabat", "strategis", "estetik",
  "instagramable", "murmer", "worth", "bintang lima",
  // English
  "good", "great", "excellent", "awesome", "amazing", "nice", "clean", "comfortable",
  "friendly", "cheap", "affordable", "beautiful", "spacious", "cozy", "love", "loved",
  "perfect", "wonderful", "fantastic", "best", "quiet", "tasty", "delicious",
];

const NEGATIVE = [
  // Indonesia
  "jelek", "buruk", "kotor", "jorok", "mahal", "sempit", "macet", "antre", "antri",
  "lama", "lambat", "lemot", "kecewa", "jangan", "rugi", "bau", "bising", "berisik",
  "panas", "sumpek", "pengap", "rusak", "tutup", "susah", "sulit", "kapok",
  "parkir susah", "parkir sulit", "tidak recommended", "nggak recommended",
  "mending", "skip", "zonk", "overpriced", "tidak ramah", "judes", "cuek",
  "kecil banget", "sempit banget", "pelayanan buruk",
  // English
  "bad", "terrible", "awful", "dirty", "expensive", "overpriced", "slow", "rude",
  "crowded", "noisy", "loud", "small", "cramped", "disappointing", "disappointed",
  "avoid", "worst", "poor", "horrible", "smelly", "broken", "closed",
];

function scoreTip(text) {
  const t = ` ${text.toLowerCase()} `;
  let pos = 0;
  let neg = 0;
  const posHits = [];
  const negHits = [];
  for (const kw of POSITIVE) {
    if (t.includes(kw)) {
      pos++;
      if (posHits.length < 3) posHits.push(kw);
    }
  }
  for (const kw of NEGATIVE) {
    if (t.includes(kw)) {
      neg++;
      if (negHits.length < 3) negHits.push(kw);
    }
  }
  return { pos, neg, posHits, negHits };
}

function snippet(text, max = 160) {
  const t = text.replace(/\s+/g, " ").trim();
  return t.length > max ? t.slice(0, max - 1).trimEnd() + "…" : t;
}

async function fsq(path, key) {
  const r = await fetch(FSQ + path, {
    headers: { ...UA, Authorization: key, Accept: "application/json" },
  });
  if (r.status === 401 || r.status === 403) {
    const e = new Error("API key Foursquare ditolak (401/403).");
    e.code = "FSQ_AUTH";
    throw e;
  }
  if (!r.ok) {
    const e = new Error(`Foursquare error ${r.status}.`);
    e.code = "FSQ_ERR";
    throw e;
  }
  return r.json();
}

async function nominatimReverse(lat, lng) {
  try {
    const r = await fetch(
      `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}&accept-language=id`,
      { headers: UA }
    );
    if (!r.ok) return null;
    const j = await r.json();
    return j.display_name || null;
  } catch {
    return null;
  }
}

async function wikipediaSummary(q) {
  // Coba Wikipedia Bahasa Indonesia dulu, fallback ke Inggris.
  for (const lang of ["id", "en"]) {
    try {
      const s = await fetch(
        `https://${lang}.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(
          q
        )}&format=json&srlimit=1&origin=*`,
        { headers: UA }
      );
      const sj = await s.json();
      const hit = sj?.query?.search?.[0];
      if (!hit) continue;
      const p = await fetch(
        `https://${lang}.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(
          hit.title.replace(/ /g, "_")
        )}`,
        { headers: UA }
      );
      const pj = await p.json();
      if (pj.extract && pj.type !== "disambiguation") {
        return { text: pj.extract, url: pj.content_urls?.desktop?.page || null, lang };
      }
    } catch {
      /* lanjut */
    }
  }
  return null;
}

function mapsLink(name, lat, lng) {
  const q = lat != null && lng != null ? `${lat},${lng}` : name;
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`;
}

export default async function handler(req, res) {
  const { q, lat, lng } = req.query;
  const name = (q || "").toString().trim();
  const la = parseFloat(lat);
  const ln = parseFloat(lng);
  const hasLL = Number.isFinite(la) && Number.isFinite(ln);

  if (!name && !hasLL) {
    return res.status(400).json({ error: "Isi nama tempat atau koordinat." });
  }

  const key = process.env.FOURSQUARE_API_KEY;
  const result = {
    name: name || null,
    lat: hasLL ? la : null,
    lng: hasLL ? ln : null,
    needsKey: !key,
    source: [],
  };

  // ---- Foursquare: cari -> detail -> tips ----
  if (key) {
    try {
      const ll = hasLL ? `&ll=${la},${ln}` : "";
      const search = await fsq(
        `/search?query=${encodeURIComponent(name || "tempat")}${ll}&limit=5&fields=fsq_id,name,geocodes,location,distance,categories`,
        key
      );
      const candidates = search.results || [];
      if (candidates.length) {
        const best = candidates[0];
        const id = best.fsq_id;
        const [detail, tipsRaw] = await Promise.all([
          fsq(
            `/${id}?fields=fsq_id,name,geocodes,location,categories,rating,hours,website,tel,price,stats,description`,
            key
          ).catch(() => null),
          fsq(`/${id}/tips?limit=30&fields=text`, key).catch(() => []),
        ]);
        const d = detail || best;
        const geo = d.geocodes?.main || {};
        result.name = d.name || result.name;
        result.lat = geo.latitude ?? result.lat;
        result.lng = geo.longitude ?? result.lng;
        result.address =
          d.location?.formatted_address ||
          [d.location?.address, d.location?.locality, d.location?.region]
            .filter(Boolean)
            .join(", ") ||
          null;
        result.categories = (d.categories || []).map((c) => c.name);
        result.rating = d.rating ?? null; // skala 10
        result.ratingCount = d.stats?.total_ratings ?? null;
        result.price = d.price ?? null; // 1-4
        result.tel = d.tel || null;
        result.website = d.website || null;
        result.hours = d.hours?.display || null;
        result.description = d.description || null;
        result.fsqId = id;
        result.source.push("Foursquare");

        const tips = (Array.isArray(tipsRaw) ? tipsRaw : tipsRaw.results || [])
          .map((t) => (typeof t === "string" ? t : t.text))
          .filter((t) => t && t.trim().length > 3);

        const scored = tips.map((text) => ({ text, ...scoreTip(text) }));
        const pros = scored
          .filter((s) => s.pos > s.neg)
          .sort((a, b) => b.pos - a.pos || b.text.length - a.text.length)
          .slice(0, 4);
        const cons = scored
          .filter((s) => s.neg > s.pos)
          .sort((a, b) => b.neg - a.neg || b.text.length - a.text.length)
          .slice(0, 4);

        result.pros = pros.map((s) => ({ text: snippet(s.text), keywords: s.posHits }));
        result.cons = cons.map((s) => ({ text: snippet(s.text), keywords: s.negHits }));
        result.tipsCount = tips.length;
        result.sampleTips = scored.slice(0, 3).map((s) => snippet(s.text, 200));
      }
    } catch (e) {
      if (e.code === "FSQ_AUTH") {
        return res.status(502).json({
          error: "API key Foursquare ditolak. Cek kembali key di env FOURSQUARE_API_KEY.",
        });
      }
      result.fsqError = e.message;
    }
  }

  // ---- Fallback/pelengkap: OSM reverse geocode untuk alamat ----
  if (!result.address && hasLL) {
    const addr = await nominatimReverse(la, ln);
    if (addr) {
      result.address = addr;
      result.source.push("OpenStreetMap");
    }
  }

  // ---- Wikipedia: ringkasan ----
  if (result.name) {
    const wiki = await wikipediaSummary(result.name);
    if (wiki) {
      result.summary = wiki.text;
      result.summaryUrl = wiki.url;
      result.source.push("Wikipedia");
    }
  }

  result.mapsUrl = mapsLink(result.name || name, result.lat, result.lng);

  if (!result.source.includes("Foursquare") && !result.address && !result.summary) {
    return res.status(404).json({
      error: "Tempat tidak ditemukan.",
      needsKey: result.needsKey,
      hint: result.needsKey
        ? "Pasang API key Foursquare di env FOURSQUARE_API_KEY untuk hasil terbaik."
        : "Coba dengan nama yang lebih spesifik atau tempel link Google Maps-nya.",
    });
  }

  return res.status(200).json(result);
}

// GET /api/route?stops=<JSON array>&konsumsi=<km/L>&harga=<Rp/L>
// stops: [{ name?, lat?, lng? }] — nama yang belum ada koordinatnya di-geocode via Nominatim.
// 1. Routing via OSRM (gratis).
// 2. POI di sepanjang rute via Overpass/OpenStreetMap: SPBU, masjid/mushola,
//    rest area, tempat makan, minimarket, ATM/bank, bengkel motor.
// 3. Estimasi BBM + saran titik istirahat.

const UA = { "User-Agent": "Mozilla/5.0 (compatible; TemanJalan/1.0)" };

function haversineKm(a, b) {
  const R = 6371;
  const dLa = ((b.lat - a.lat) * Math.PI) / 180;
  const dLn = ((b.lng - a.lng) * Math.PI) / 180;
  const s =
    Math.sin(dLa / 2) ** 2 +
    Math.cos((a.lat * Math.PI) / 180) *
      Math.cos((b.lat * Math.PI) / 180) *
      Math.sin(dLn / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(s));
}

async function geocode(name) {
  const r = await fetch(
    `https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q=${encodeURIComponent(
      name
    )}&accept-language=id`,
    { headers: UA }
  );
  if (!r.ok) throw new Error(`Geocode gagal untuk "${name}".`);
  const j = await r.json();
  if (!j.length) throw new Error(`Lokasi "${name}" tidak ditemukan.`);
  return { name, lat: parseFloat(j[0].lat), lng: parseFloat(j[0].lon) };
}

// Ambil titik sampel tiap ~10 km (maks 40 titik) untuk query Overpass.
function sampleRoute(coords) {
  // coords: [[lng, lat], ...] dari OSRM
  const pts = coords.map(([lng, lat]) => ({ lat, lng }));
  const cum = [0];
  for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + haversineKm(pts[i - 1], pts[i]));
  const total = cum[cum.length - 1] || 0;
  const step = Math.max(total / 40, 10); // km
  const samples = [{ ...pts[0], km: 0 }];
  let next = step;
  for (let i = 1; i < pts.length; i++) {
    if (cum[i] >= next) {
      samples.push({ ...pts[i], km: cum[i] });
      next += step;
    }
  }
  samples.push({ ...pts[pts.length - 1], km: total });
  return { samples, totalKm: total };
}

function overpassQuery(samples) {
  const rules = [
    ["nwr", "amenity", "fuel"],
    ["nwr", "amenity", "place_of_worship"],
    ["nwr", "highway", "rest_area"],
    ["nwr", "amenity", "restaurant"],
    ["nwr", "amenity", "cafe"],
    ["nwr", "amenity", "fast_food"],
    ["nwr", "shop", "convenience"],
    ["nwr", "amenity", "atm"],
    ["nwr", "amenity", "bank"],
    ["nwr", "shop", "motorcycle"],
    ["nwr", "amenity", "vehicle_repair"],
  ];
  const arounds = samples
    .map((s) => rules.map(([t, k, v]) => `${t}(around:2500,${s.lat},${s.lng})["${k}"="${v}"];`).join("\n"))
    .join("\n");
  return `[out:json][timeout:60];\n(\n${arounds}\n);\nout center tags;`;
}

function labelPoi(tags) {
  const get = (k) => tags[k];
  if (get("amenity") === "fuel") return { cat: "spbu", label: "SPBU" };
  if (get("amenity") === "place_of_worship") {
    const rel = (get("religion") || "").toLowerCase();
    return rel === "muslim"
      ? { cat: "ibadah", label: "Masjid/Mushola" }
      : { cat: "ibadah", label: "Tempat Ibadah" };
  }
  if (get("highway") === "rest_area") return { cat: "rest", label: "Rest Area" };
  if (["restaurant", "cafe", "fast_food"].includes(get("amenity")))
    return { cat: "makan", label: "Tempat Makan" };
  if (get("shop") === "convenience") return { cat: "minimarket", label: "Minimarket" };
  if (["atm", "bank"].includes(get("amenity"))) return { cat: "atm", label: "ATM/Bank" };
  if (get("shop") === "motorcycle" || get("amenity") === "vehicle_repair")
    return { cat: "bengkel", label: "Bengkel Motor" };
  return null;
}

function fmtDur(min) {
  const h = Math.floor(min / 60);
  const m = Math.round(min % 60);
  return h ? `${h} jam ${m} mnt` : `${m} mnt`;
}

export default async function handler(req, res) {
  let stops;
  try {
    stops = JSON.parse(req.query.stops || "[]");
  } catch {
    return res.status(400).json({ error: "Parameter 'stops' bukan JSON valid." });
  }
  if (!Array.isArray(stops) || stops.length < 2) {
    return res.status(400).json({ error: "Minimal 2 titik: asal dan tujuan." });
  }

  const konsumsi = parseFloat(req.query.konsumsi) || 40; // km per liter
  const harga = parseFloat(req.query.harga) || 10000; // Rp per liter

  try {
    // 1. Geocode titik yang belum punya koordinat
    const pts = [];
    for (const s of stops.slice(0, 10)) {
      if (Number.isFinite(s.lat) && Number.isFinite(s.lng)) {
        pts.push({ name: s.name || `${s.lat},${s.lng}`, lat: s.lat, lng: s.lng });
      } else if (s.name) {
        pts.push(await geocode(s.name));
      }
    }
    if (pts.length < 2) {
      return res.status(400).json({ error: "Titik asal/tujuan tidak bisa dikenali." });
    }

    // 2. Routing OSRM
    const coordStr = pts.map((p) => `${p.lng},${p.lat}`).join(";");
    const osrmUrl =
      `https://router.project-osrm.org/route/v1/driving/${coordStr}` +
      `?overview=full&geometries=geojson`;
    const or = await fetch(osrmUrl, { headers: UA });
    if (!or.ok) throw new Error("Layanan rute (OSRM) sedang bermasalah. Coba lagi.");
    const oj = await or.json();
    const route = oj.routes?.[0];
    if (!route) throw new Error("Rute tidak ditemukan.");

    const distanceKm = route.distance / 1000;
    const durationMin = route.duration / 60;
    const { samples, totalKm } = sampleRoute(route.geometry.coordinates);

    // 3. POI via Overpass (coba beberapa mirror berurutan)
    let pois = [];
    const MIRRORS = [
      "https://overpass-api.de/api/interpreter",
      "https://overpass.kumi.systems/api/interpreter",
      "https://overpass.nchc.org.tw/api/interpreter",
    ];
    const query = overpassQuery(samples);
    for (const mirror of MIRRORS) {
      try {
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), 25000);
        const qr = await fetch(mirror, {
          method: "POST",
          headers: { ...UA, "Content-Type": "application/x-www-form-urlencoded" },
          body: "data=" + encodeURIComponent(query),
          signal: ctrl.signal,
        });
        clearTimeout(timer);
        if (!qr.ok) continue;
        const qj = await qr.json();
        if (!qj.elements) continue;
        const seen = new Set();
        for (const el of qj.elements || []) {
          const id = `${el.type}/${el.id}`;
          if (seen.has(id)) continue;
          seen.add(id);
          const tags = el.tags || {};
          const kind = labelPoi(tags);
          if (!kind) continue;
          const plat = el.lat ?? el.center?.lat;
          const plng = el.lon ?? el.center?.lon;
          if (plat == null || plng == null) continue;
          // jarak & progres terhadap rute
          let best = { d: Infinity, km: 0 };
          for (const s of samples) {
            const d = haversineKm({ lat: plat, lng: plng }, s);
            if (d < best.d) best = { d, km: s.km };
          }
          if (best.d > 3) continue; // hanya yang dekat rute (<=3 km)
          pois.push({
            id,
            name: tags.name || kind.label,
            ...kind,
            lat: plat,
            lng: plng,
            distFromRouteKm: Math.round(best.d * 10) / 10,
            routeKm: Math.round(best.km),
          });
        }
        // urut per kategori lalu progres rute; batasi 8 per kategori
        const byCat = {};
        for (const p of pois.sort((a, b) => a.routeKm - b.routeKm)) {
          (byCat[p.cat] = byCat[p.cat] || []).push(p);
        }
        pois = Object.values(byCat).flatMap((arr) => arr.slice(0, 8));
        if (pois.length) break; // sukses — tidak perlu coba mirror lain
      } catch {
        /* coba mirror berikutnya */
      }
    }

    // 4. Estimasi BBM
    const fuelL = distanceKm / konsumsi;
    const fuelRp = fuelL * harga;

    // 5. Saran istirahat tiap 100 km: cari POI rest/ibadah/spbu terdekat
    const restStops = [];
    for (let km = 100; km < totalKm; km += 100) {
      const cand = pois
        .filter((p) => ["rest", "ibadah", "spbu"].includes(p.cat))
        .sort((a, b) => Math.abs(a.routeKm - km) - Math.abs(b.routeKm - km))[0];
      if (cand) restStops.push({ atKm: km, poi: cand });
    }

    // Geometri disederhanakan untuk peta (maks 400 titik)
    const geom = route.geometry.coordinates.filter(
      (_, i, a) => a.length <= 400 || i % Math.ceil(a.length / 400) === 0
    );

    return res.status(200).json({
      stops: pts,
      distanceKm: Math.round(distanceKm * 10) / 10,
      duration: fmtDur(durationMin),
      durationMin: Math.round(durationMin),
      fuel: {
        konsumsi,
        harga,
        liter: Math.round(fuelL * 10) / 10,
        rupiah: Math.round(fuelRp),
      },
      geometry: geom,
      pois,
      restStops,
      warnings: [
        "Rute dihitung untuk kendaraan roda 4 — motor dilarang masuk jalan tol. Periksa rambu di jalan.",
        "Waktu tempuh tanpa memperhitungkan macet & kondisi jalan.",
      ],
    });
  } catch (e) {
    return res.status(502).json({ error: e.message || "Gagal menghitung rute." });
  }
}
